import{_ as e,c as i,o as l,ag as t}from"./chunks/framework.C86mscM5.js";const m=JSON.parse('{"title":"APM","description":"","frontmatter":{},"headers":[],"relativePath":"devops/observability/apm/index.md","filePath":"devops/observability/apm/index.md","lastUpdated":1788689791000}'),r={name:"devops/observability/apm/index.md"};function o(n,a,s,c,d,p){return l(),i("div",null,a[0]||(a[0]=[t('<h1 id="apm" tabindex="-1">APM <a class="header-anchor" href="#apm" aria-label="Permalink to &quot;APM&quot;">​</a></h1><p>APM（Application Performance Monitoring/Management）从服务端观察请求、事务、依赖调用、错误和资源消耗，用来发现慢请求、错误热点和跨服务瓶颈。</p><h2 id="最小数据模型" tabindex="-1">最小数据模型 <a class="header-anchor" href="#最小数据模型" aria-label="Permalink to &quot;最小数据模型&quot;">​</a></h2><ul><li>服务、环境、版本和实例标识。</li><li>请求名称、状态、耗时和错误。</li><li>数据库、缓存、消息队列及外部 HTTP 调用。</li><li>Trace/Span 上下文与结构化日志关联。</li><li>部署事件与性能变化的时间关联。</li></ul><h2 id="接入步骤" tabindex="-1">接入步骤 <a class="header-anchor" href="#接入步骤" aria-label="Permalink to &quot;接入步骤&quot;">​</a></h2><ol><li>从一个关键服务和关键路径开始，定义成功率与延迟 SLI。</li><li>使用 OpenTelemetry SDK 或厂商 Agent 采集 Trace、Metrics 和错误。</li><li>通过 Collector 完成批处理、采样、脱敏和导出。</li><li>在 Dashboard 中关联服务版本、依赖和日志。</li><li>用 SLO 消耗和用户影响告警，而不是对每条异常告警。</li></ol><h2 id="工具边界" tabindex="-1">工具边界 <a class="header-anchor" href="#工具边界" aria-label="Permalink to &quot;工具边界&quot;">​</a></h2><ul><li>Elastic APM、Grafana Stack、Jaeger、Tempo 以及商业 APM 都可作为后端。</li><li>Prometheus 主要存储时序指标；ELK/Elastic Stack 常用于日志检索和分析。</li><li>APM 不能替代业务埋点、基础设施监控或真实用户监控。</li></ul><p>Elastic 组件原理参见 <a href="./../../../server/elastic/apm.html">Server/Elastic</a>，浏览器侧参见 <a href="./../rum/">RUM</a>。</p>',9)]))}const _=e(r,[["render",o]]);export{m as __pageData,_ as default};
